get binaryType () {
  webidl.brandCheck(this, WebSocket)

  return this.#binaryType
}

set binaryType (type) {
  webidl.brandCheck(this, WebSocket)

  if (type !== 'blob' && type !== 'arraybuffer') {
    this.#binaryType = 'blob'
  } else {
    this.#binaryType = type
  }
}

