    const socket = ws._socket

    socket.write(Buffer.from([0x01, 0x00])) // Empty text frame, fin not set
    socket.write(Buffer.from([0x00, 0x00])) // Empty continuation frame, fin not set
    socket.write(Buffer.from([0x80, 0x05, 0x48, 0x65, 0x6c, 0x6c, 0x6f])) // Continuation "Hello", fin set
  })

  const client = new WebSocket(`ws://127.0.0.1:${server.address().port}`)

  const [{ data }] = await once(client, 'message')
