 * resolves once *both* endpoints have observed the close.
 *
 * @param {import('node:test').TestContext} t
 * @param {{ perMessageDeflate?: object, fragment: Buffer, count: number }} options
 */
async function assertTooManyFragments (t, { perMessageDeflate, fragment, count }) {
  const agent = new Agent({
    webSocket: {
      maxFragments: 3
    }
  })

  t.after(() => agent.close())

  const server = new WebSocketServer({ perMessageDeflate, port: 0 })

  t.after(() => server.close())

  const serverClosed = new Promise((resolve) => {
    server.on('connection', (ws) => {
      ws.on('close', (code, reason) => resolve([code, reason]))

      for (let i = 0; i < count; i++) {
